const body = $json.body ?? $json;
const input = String(body.text || '').trim();
const lead = body.lead ?? {};
const email = String(lead.email || body.email || '').trim().toLowerCase();
const name = String(lead.name || '').trim();
const whatsapp = String(lead.whatsapp || lead.phone || body.from || '').trim();
const whatsappUrl = body.whatsappUrl || 'https://wa.me/59899576144?text=Hola%2C%20quiero%20consultar%20por%20un%20producto%20del%20catalogo.';
const catalog = Array.isArray(body.catalog) ? body.catalog : [];
const source = String(body.source || 'website-chat');
const site = String(body.site || 'Casa Medanos');
const sessionId = String(body.sessionId || '');

const normalize = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const tokenize = value => normalize(value).split(/[^a-z0-9]+/).filter(token => token.length > 2 && !['que','tenes','tienes','para','por','con','del','las','los','una','uno','quiero','busco','necesito','algo','ver','mostrar','mostrame','disponible','disponibles','queda','quedan'].includes(token));

const intents = {
  categories: [
    { value: 'electro', terms: ['electro', 'electrodomestico', 'heladera', 'microondas', 'lavarropa', 'tostadora', 'jarra', 'monitor', 'tv', 'televisor'] },
    { value: 'mueble', terms: ['mueble', 'ropero', 'mesa', 'silla', 'biblioteca', 'sillon', 'modular'] },
    { value: 'libros', terms: ['libro', 'libros'] },
    { value: 'decoracion', terms: ['decoracion', 'mantel'] }
  ],
  rooms: [
    { value: 'Living', terms: ['living'] },
    { value: 'Dormitorio', terms: ['dormitorio'] },
    { value: 'Cocina', terms: ['cocina'] },
    { value: 'Comedor', terms: ['comedor'] },
    { value: 'Escritorio', terms: ['escritorio'] },
    { value: 'Bano', terms: ['bano', 'baño'] }
  ]
};

const detectIntent = (query) => {
  const normalized = normalize(query);
  return {
    normalized,
    tokens: tokenize(query),
    categories: intents.categories.filter(entry => entry.terms.some(term => normalized.includes(normalize(term)))).map(entry => entry.value),
    rooms: intents.rooms.filter(entry => entry.terms.some(term => normalized.includes(normalize(term)))).map(entry => entry.value),
    wantsAll: /todo|todos|catalogo|completo|disponible|disponibles/.test(normalized),
    wantsCheapest: /barato|economico|oferta|menos de/.test(normalized),
    asksShipping: /retiro|entrega|flete|medanos|solymar|direccion|ubicacion/.test(normalized)
  };
};

const categoryMatchesIntent = (item, intent) => {
  if (!intent.categories.length) return true;
  const category = normalize(item.category);
  const itemName = normalize(item.name);
  return intent.categories.some(match => category.includes(match) || itemName.includes(match));
};

const roomMatchesIntent = (item, intent) => {
  if (!intent.rooms.length) return true;
  return intent.rooms.some(match => normalize(item.room) === normalize(match));
};

const searchCatalog = (query, limit = 3) => {
  const intent = detectIntent(query);
  const exact = catalog.filter(item => intent.normalized.length >= 4 && normalize(item.name).includes(intent.normalized));
  if (exact.length) return exact.slice(0, limit);

  return catalog
    .filter(item => categoryMatchesIntent(item, intent) && roomMatchesIntent(item, intent))
    .map(item => {
      const normalizedName = normalize(item.name);
      const normalizedMeta = normalize(`${item.category} ${item.room}`);
      const nameHits = intent.tokens.filter(token => normalizedName.includes(token)).length;
      const metaHits = intent.tokens.filter(token => normalizedMeta.includes(token)).length;
      let score = nameHits * 5 + metaHits * 2;
      if (intent.categories.length) score += 3;
      if (intent.rooms.length) score += 2;
      if (intent.normalized && normalizedName.includes(intent.normalized)) score += 10;
      return { item, score, nameHits, metaHits };
    })
    .filter(entry => {
      if (intent.wantsAll && (intent.categories.length || intent.rooms.length)) return true;
      if (intent.categories.length || intent.rooms.length) return entry.score >= 3;
      return entry.nameHits > 0 || entry.score >= 6;
    })
    .sort((left, right) => right.score - left.score || Number(left.item.price || 0) - Number(right.item.price || 0))
    .slice(0, limit)
    .map(entry => entry.item);
};

const cheapest = [...catalog].sort((left, right) => Number(left.price || 0) - Number(right.price || 0)).slice(0, 3);
const intent = detectIntent(input);
let reply = '';
let suggestions = [];
let next_actions = [
  { label: 'Electrodomesticos', prompt: 'Que electrodomesticos tenes disponibles?' },
  { label: 'Muebles', prompt: 'Mostrame muebles para dormitorio' },
  { label: 'Retiro y flete', prompt: 'Como se coordina el retiro y el flete?' },
  { label: 'WhatsApp', type: 'url', url: whatsappUrl }
];

if (!email) {
  return [{ json: { success: false, requires_email: true, reply: 'Antes de seguir necesito tu email para enviarte informacion y registrar la consulta.', suggestions: [], whatsapp_url: whatsappUrl, next_actions } }];
}

if (!input) {
  reply = 'Decime que producto, ambiente o categoria te interesa y te respondo con opciones concretas.';
} else if (intent.asksShipping) {
  reply = 'El retiro se coordina en Medanos de Solymar. Si preferis, segui por WhatsApp y queda registrada tu consulta.';
  next_actions = [
    { label: 'Seguir por WhatsApp', type: 'url', url: whatsappUrl },
    { label: 'Living', type: 'filter_room', value: 'Living' },
    { label: 'Cocina', type: 'filter_room', value: 'Cocina' },
    { label: 'Dormitorio', type: 'filter_room', value: 'Dormitorio' }
  ];
} else if (intent.wantsCheapest) {
  reply = 'Estas son las opciones mas accesibles que siguen disponibles ahora.';
  suggestions = cheapest;
} else {
  suggestions = searchCatalog(input, 3);
  if (suggestions.length) {
    reply = suggestions.length === 1
      ? 'Encontre una coincidencia clara con lo que buscas.'
      : 'Estas son las coincidencias mas relevantes para tu consulta.';
    next_actions = [
      { label: 'Seguir por WhatsApp', type: 'url', url: whatsappUrl },
      { label: 'Retiro y flete', prompt: 'Como se coordina el retiro y el flete?' },
      { label: 'Lo mas barato', prompt: 'Cual es lo mas barato que queda?' }
    ];
  } else if (intent.wantsAll && (intent.categories.length || intent.rooms.length)) {
    suggestions = catalog.filter(item => categoryMatchesIntent(item, intent) && roomMatchesIntent(item, intent)).slice(0, 3);
    reply = suggestions.length
      ? 'Te muestro lo mas relevante de ese ambiente o categoria.'
      : 'No encontre articulos activos para ese filtro puntual.';
  } else {
    reply = 'No encontre una coincidencia suficientemente clara. Proba con el nombre del producto, ambiente o categoria exacta, o segui por WhatsApp.';
    next_actions = [
      { label: 'WhatsApp', type: 'url', url: whatsappUrl },
      { label: 'Muebles', prompt: 'Mostrame muebles para dormitorio' },
      { label: 'Electrodomesticos', prompt: 'Que electrodomesticos tenes disponibles?' }
    ];
  }
}

const staticData = $getWorkflowStaticData('global');
staticData.leads = Array.isArray(staticData.leads) ? staticData.leads : [];
staticData.leads.unshift({
  created_at: new Date().toISOString(),
  session_id: sessionId,
  source,
  site,
  lead: { email, name, whatsapp },
  query: input,
  suggestions: suggestions.map(item => ({ name: item.name, price: item.price, category: item.category, room: item.room })),
  whatsapp_url: whatsappUrl
});
staticData.leads = staticData.leads.slice(0, 500);

return [{
  json: {
    success: true,
    requires_email: false,
    reply,
    suggestions,
    whatsapp_url: whatsappUrl,
    next_actions,
    lead: { email, name, whatsapp },
    registered: true,
    registry_size: staticData.leads.length
  }
}];
